-- まさ指示：未見積費の概算と自社FAME採算。データのみ、適用済みなら再実行禁止。
begin;
select set_config('amd.cost_change_reason','まさ指示: 追加分析機器・送気前処理・開始資金の概算を入力し自社FAMEの成立性を確認',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from '46a862c263fa37c9dc241882db31b4ee' then raise exception 'fuel changed: project_cost_models'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from 'c81bb40c4b9fb881574732775af5dd2a' then raise exception 'fuel changed: project_cost_assumptions'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b80c6219e74a52ef6ace596640168f64' then raise exception 'fuel changed: project_cost_items'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from '482096022c7df05d66d1fc332098d127' then raise exception 'fuel changed: project_cost_tasks'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from 'e42ca95d8661d92e387ce30a5b9646d0' then raise exception 'fuel changed: project_cost_notes'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '0fcd1c6c7f000ab8d00d11ac4f1396d2' then raise exception 'effluent assumptions changed'; end if;
end $$;
update project_cost_assumptions set value=1200000,note='現在の排水連動・基準収率・CO₂濃度5%用の概算120万円/年。脂肪酸109796.47kg×CO₂供給3.48kg/kg÷1.964kg/Nm³÷5%＝約389万Nm³/年。追加差圧20kPa・総合効率55%で約39303kWh、17.45円/kWhで約68.6万円→電力70万円、追い冷却・凝縮水・フィルタ25万円、送気設備の部品/外注保守25万円。既設で冷却・除塵済みの排ガスを近距離分岐する条件。新規のCO₂分離濃縮・大規模脱硫・長距離配管は含まない。共通培養の送気電力は再計上しない。空気/濃度/規模を変えたら供給量・電力・年額を再見積。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_auto_carbon_delivery_annual' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=200000,note='分析機器の追加校正10万円＋保守5万円＋電力等5万円＝20万円/年を内部概算。日常試薬・消耗品1000円/ロット、外部確認15万円×年12回とは重ねない。委託先見積・保守契約は未取得。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_auto_lab_annual' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=2000000,note='日常の酸価・水分管理用の追加購入200万円（税別の内部予算）。HIRANUMA COM-28/28S 81.2万円～、AQ-300 75万円～を参考に、電極・天秤・据付等43.8万円を仮置き。GCは購入せず組成等は定期外注側。全規格試験を内製できる構成ではない。機器構成・据付の見積未取得。https://www.hiranuma.com/product/titr/ https://www.hiranuma.com/product/aqua/ 2026-10-17閲覧。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_auto_lab_capex' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=300000,note='燃料回収で増えるシール・部品10万円＋回収系計器の点検校正10万円＋追加の薬液廃棄10万円＝30万円/年の内部予算。作業欄の追加人時、既存薬品・溶媒補給・吸着材・熱電力、送気保守、分析機器維持と別。共有培養の通常保守・人員配賦を加えない。設備利用料・菌体出荷の損失は発生しない条件で、未確認のリスク。自社FAME設備を買う比較では追加保守をここへ足す。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_op_inventory_incremental_annual' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=0,note='既存の透光性のある閉鎖培養・保管設備と敷地をそのまま利用し、屋外新設・移設を行わない条件の追加購入0円という仮定。設備共用と太陽光の利用可否は未確認で、確認済み0円ではない。新設/改修が必要なら実際の差額へ置き換える。送気の350万円と分析機器200万円は別欄で計上。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_op_sunlight_capex' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=0,note='既存の場所・管理を共用し、太陽光化だけの追加賃料・夜間維持は生じない条件の仮定0円。燃料回収の増分は追加運転費30万円/年、送気120万円/年、分析20万円/年へ分けて計上。共用できない場合や出荷遅延・菌体品質への影響が出る場合は差額へ置き換える。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_op_sunlight_opex_annual' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=3500000,note='燃料用の追加送気・前処理だけ350万円（内部予算）。ブロワ100万円＋追い冷却/凝縮水分離/フィルタ80万円＋分岐配管70万円＋制御50万円＋据付50万円。分析機器200万円は別欄。既存培養・保管槽を買い直さず、回収・FAME転換も既存能力を使える条件。これらの共用可否・送気設備の流量性能・材質・工事費は未確認。新規FAME専用設備が必要ならその差額のみ追加入力。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_shared_inventory_equipment_capex' and cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set value=457485290,note='現在の平均出荷待ち液20332.68m³×初期溶媒5%×45万円/m³＝約4億5749万円。既存モデルの5%仮定を開始資金として概算したもので、必要性・回収率・価格・在庫共用は未検証。年間原価に一括計上/償却せず、消耗補給費とも重ねない。規模変更時は液量から再計算。仮に1%なら約9149.7万円、5%なら本額で、この範囲も十分性を示さない。資金調達費は主原価に未算入。3%/年なら約1372.5万円/年を追加運転費へ上乗せして別試算する。',confidence='H',source_kind='仮置き',owner='AMD（内部）',updated_at=now() where cost_assumption_id='caf_shared_inventory_initial_working_capital' and cost_model_id='cm_p21_fuel_260914';
update project_cost_models set version_label='261017 追加費の概算・自社FAME採算',summary_md='排水処理の出荷待ち菌体から作れるFAME量に対して、自動運転の追加費と自社転換・外部委託の採算を比較する。送気・前処理、日常分析機器の購入・維持、回収の追加運転費を見積前の概算で計上。初回溶媒は開始資金として年間原価と分ける。',system_scope_md='既存の培養・保管・回収・FAME設備を共用できる条件の追加採算。追加送気・前処理設備350万円、日常分析機器200万円を一度ずつ償却し、送気120万円/年・分析維持20万円/年・回収の追加運転30万円/年を加算する。太陽光用の新設や追加賃料は不要という仮定。初回溶媒5%は未検証で、現在の液量では約4.57億円の開始資金。金利・資本コスト・税・本社共通費は主原価に未算入。全て内部予算で供給者見積や技術実証ではなく、設備共用・太陽光生産性・追加人時も未確認。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='概算を入れた採算と共用条件',body_md='送気の追加設備350万円・送気運転120万円/年、日常分析の機器200万円・維持20万円/年、回収の追加部品・計器・廃棄30万円/年を内部概算。培養・保管・回収・自社FAME設備は既存能力の共用を仮定し、その購入を再計上しない。太陽光用の新設・追加賃料も不要という仮定。全て見積前のH。外部確認は年12回×15万円の仮置きで、必要な項目・頻度は未合意。' where cost_note_id='cnf_caveat_biomass' and cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='開始資金と自社FAME装置の共用を別確認',body_md='初回溶媒を現在の液量の5%で持つと約4.57億円。これは未検証の既存モデルの仮定であり、必要量が確定した意味ではない。年間の消耗補給とは別の開始資金で、主原価へ償却しない。金利・資本コストは主原価に含まない。回収・自社FAME設備を既存で賄えるかも未確認。新規設備が必要なら、その差額と維持だけを追加する。培養槽の再購入ではない。' where cost_note_id='cnf_caveat_line' and cost_model_id='cm_p21_fuel_260914';
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_est_lab_261017','cm_p21_fuel_260914','benchmark','分析機器200万円の概算根拠','2026-10-17のメーカー公開価格を参照。自動滴定COM-28/28S 81.2万円～、微量水分計AQ-300 75万円～。電極・天秤・据付等43.8万円を内部仮置きし合計200万円、7年償却。校正・保守・電力等は年20万円。日常の酸価・水分管理を対象とし、GC購入や全規格分析の内製は含まない。組成等の外部確認は作業欄の年12回×15万円で残す。税込表示の価格を混ぜず税別の内部予算として扱う。公開価格は最低構成の参考で、SOL向け一式見積ではない。水分計: https://www.hiranuma.com/product/aqua/','HIRANUMA公開価格（2026-10-17閲覧）','https://www.hiranuma.com/product/titr/','amd_internal',24);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_est_gas_261017','cm_p21_fuel_260914','benchmark','送気・前処理の概算条件','基準条件の脂肪酸約109.8t/年に対しCO₂供給3.48kg/kg（吸収約80%の旧仮定）、排ガスCO₂5%で約389万Nm³/年。年間300日×日中12時間なら約1081Nm³/h。差圧20kPa・効率55%で約3.93万kWh/年→電力70万円、追い冷却・凝縮水/フィルタ25万円、部品・保守25万円。購入予算は送気100万円＋前処理80万円＋配管70万円＋制御50万円＋据付50万円＝350万円。既設の冷却・除塵後から近距離分岐する想定で、濃縮CO₂購入・新規分離濃縮・大規模脱硫・長距離送気は含まない。差圧と吸収率は実測前、ブロワ性能や必要台数を保証する見積ではない。空気は同じ炭素量に約125倍のガス量が必要なので、この年額をそのまま流用せず再見積する。','物質収支・送気仕事からの内部概算（2026-10-17）',null,'amd_internal',25);
insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_est_viability_261017','cm_p21_fuel_260914','caveat','自社FAMEの成立性：現在の保存条件での比較','2026-10-17保存条件の基準収率・排ガス・太陽光・自社日常分析ではFAME年106744.6L、自社転換200.64円/L、売価200円/Lに対して年6.85万円の赤字（資金調達費・税・本社共通費前）。委託262.52円/L。見積幅の比較は自社192.01～222.59円/Lで黒字を確認したとはいえない。既存FAME能力を使えず参考500万円/系列×6系列を追加購入し保守3%/年を足すと249.22円/L。回収装置を新規購入する分はこの比較にも別途必要。初回溶媒4.57億円に仮の資金コスト3%をかけると自社329.22円/L。開始資金と年間補給費は二重計上していない。排水量を約9.37%へ下げFAME年10000Lになる比較では、同じ設備予算・固定費を残して送気電力70万円分と初回溶媒を比例縮小すると562.19円/L、年362.2万円赤字、初回溶媒4285.8万円。これは小型化した設備の見積ではない。数量は排水事業の菌体使用量からの出力で、燃料年産の手入力には戻さない。各比較はここに記載した保存条件の記録で、画面で条件を変えた結果は右側の再計算を参照する。','内部概算の比較（2026-10-17、全項目未見積）',null,'amd_internal',26);
do $$ begin
 if (select count(*) from project_cost_assumptions where cost_model_id='cm_p21_fuel_260914') <> 77 or (select count(*) from project_cost_notes where cost_model_id='cm_p21_fuel_260914') <> 27 then raise exception 'unexpected row counts'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b80c6219e74a52ef6ace596640168f64' then raise exception 'item changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from '482096022c7df05d66d1fc332098d127' then raise exception 'task changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '0fcd1c6c7f000ab8d00d11ac4f1396d2' then raise exception 'effluent changed'; end if;
end $$;
commit;
